1	//! cpufreq sysfs reads, in two jobs: what the CPU is doing *now*, and what it has been *told to
2	//! do*. Never writes: reading is diagnosis, while setting a governor needs root and is global
3	//! and persistent, so a benchmark that mutated one would outlive itself.
4	//!
5	//! - **Delivered frequency** ([`avg_freq`], [`max_freq`]) feeds the warm loop's clock gate:
6	//!   `cpuinfo_avg_freq` where the driver provides it (amd-pstate), nothing otherwise.
7	//!   `scaling_cur_freq` is deliberately not a fallback: some drivers report the *requested*
8	//!   rather than the delivered frequency, and a gate fed requested values would certify a dwell
9	//!   as the top. Read the honest file where it exists and fall back to timing-only everywhere
10	//!   else.
11	//! - **Policy** ([`policy`], [`Policy`], [`PolicyField`]) is the standing configuration: which
12	//!   driver, governor, EPP and boost setting the box is running under. It is provenance, not
13	//!   measurement, and it exists because no report before 0.25.0 recorded it: the same bench
14	//!   measured 8.9% apart under `powersave` and `performance` on a 3900X, so any A/B spanning a
15	//!   policy change read an environmental delta as a code change.
16	
17	/// One delivered-frequency sample: which logical CPU it was read on, and the kHz value.
18	#[derive(Debug, Clone, Copy)]
19	pub struct FreqSample {
20	    /// Logical CPU the calling thread was on at the read.
21	    pub cpu: usize,
22	    /// Delivered frequency (kHz) as the driver reports it.
23	    pub khz: u64,
24	}
25	
26	/// Sample the calling thread's current CPU and its delivered frequency; `None` when the driver
27	/// does not expose `cpuinfo_avg_freq` (see the module doc) or the read fails.
28	pub fn avg_freq() -> Option<FreqSample> {
29	    let cpu = current_cpu()?;
30	    let khz = read_khz(cpu, "cpuinfo_avg_freq")?;
31	    Some(FreqSample { cpu, khz })
32	}
33	
34	/// The hardware maximum (kHz) for `cpu`, for the reported ratio; `None` when unavailable.
35	pub fn max_freq(cpu: usize) -> Option<u64> {
36	    read_khz(cpu, "cpuinfo_max_freq")
37	}
38	
39	/// Relative band the delivered clock must hold across a window's samples to count as stable
40	/// under load ([`clock_stable`]).
41	///
42	/// - Stability, never a fraction of `cpuinfo_max_freq`: a max-fraction threshold would need
43	///   tuning per box (96.1% sustained on the 3900X against 99.7% on the 7600x) and a
44	///   thermally-limited laptop plateaus lower still while that plateau is its honest clock.
45	/// - One percent, the same scale as the timing signals' A cutoffs: the measured dwell-to-top
46	///   step is +12.4%, an order of magnitude above the band.
47	const FREQ_STABLE_TOL: f64 = 0.01;
48	
49	/// Whether the delivered clock held still across a window's samples: the gate the warm exit
50	/// and the settle scan share, so "settled" means the same thing at both sites.
51	///
52	/// - Anything short of clean same-CPU readings falls back to timing-only (`true`): a missing
53	///   `cpuinfo_avg_freq` (the read is amd-pstate-specific) or a mid-window migration of an
54	///   unpinned main means there is no honest per-core series to gate on.
55	pub(crate) fn clock_stable(samples: &[Option<FreqSample>]) -> bool {
56	    let mut min = u64::MAX;
57	    let mut max = 0u64;
58	    let mut cpu: Option<usize> = None;
59	    for s in samples {
60	        let Some(f) = s else { return true };
61	        match cpu {
62	            None => cpu = Some(f.cpu),
63	            Some(c) if c != f.cpu => return true,
64	            Some(_) => {}
65	        }
66	        min = min.min(f.khz);
67	        max = max.max(f.khz);
68	    }
69	    if max == 0 {
70	        return true;
71	    }
72	    (max - min) as f64 / max as f64 <= FREQ_STABLE_TOL
73	}
74	
75	/// The calling thread's current logical CPU (`sched_getcpu`), `None` on syscall failure.
76	fn current_cpu() -> Option<usize> {
77	    let cpu = unsafe { libc::sched_getcpu() };
78	    usize::try_from(cpu).ok()
79	}
80	
81	/// One cpufreq sysfs value (kHz) for `cpu`, `None` when the file is absent or unparsable.
82	fn read_khz(cpu: usize, name: &str) -> Option<u64> {
83	    let path = format!("/sys/devices/system/cpu/cpu{cpu}/cpufreq/{name}");
84	    std::fs::read_to_string(path).ok()?.trim().parse().ok()
85	}
86	
87	/// One policy value, plus whether every CPU that exposes it agrees.
88	///
89	/// Paired with the `Option` in [`Policy`], this encodes three states a bare string cannot:
90	///
91	/// - **absent** (`None`): the knob does not exist on this box. rpi5-20cd exposes no
92	///   `energy_performance_preference` at all, and a printed default there would describe a
93	///   policy the machine does not have.
94	/// - **present and uniform**: the box has one policy, the ordinary case.
95	/// - **present and split**: cpufreq exposes these files per *policy group*, so nothing stops
96	///   `cpu0` reading `powersave` while `cpu8` reads `performance`. One CPU's token printed as
97	///   the box's policy would be a quiet lie in the block that exists to be provenance.
98	///
99	/// The token is kept **raw**: never an enum, never prettied. A governor some future kernel adds
100	/// should reach a record under its real name rather than as `Unknown`, and a record should say
101	/// what the machine said. Prettying belongs at the print site, which is all `boost_word` does
102	/// when it turns `1` into `enabled`.
103	///
104	/// Three consumers, one shape, which is why the flag travels with the value rather than being
105	/// resolved at the read:
106	///
107	/// - the `Setup:` block prints it, marking a split box `(mixed across CPUs)` so the reader is
108	///   never handed one CPU's token as the machine's answer;
109	/// - the per-run record serializes both parts, so a policy that was split when the numbers were
110	///   taken can still be seen years later;
111	/// - `qualify-environment` reads it as a fitness precondition, where a split box is a finding in
112	///   its own right and not a value to average away.
113	#[derive(Debug, Clone, PartialEq, Eq, serde::Serialize)]
114	pub struct PolicyField {
115	    /// The first CPU's raw sysfs token.
116	    pub value: String,
117	    /// True when every CPU exposing this file reports the same token.
118	    pub uniform: bool,
119	}
120	
121	/// The box's cpufreq policy: the knobs that decide how the CPU picks a frequency.
122	///
123	/// Every field is an `Option` because absence is a real answer, not a default to invent:
124	/// rpi5-20cd's cpufreq exposes no `energy_performance_preference` at all, and a printed
125	/// `performance` there would describe a policy the box does not have.
126	///
127	/// - `boost` falls back to the global `cpufreq/boost` when no per-CPU file exists. Intel's
128	///   inverted `intel_pstate/no_turbo` is deliberately not read: no box in this project's fleet
129	///   runs it, and a silent sign error is worse than an absent row.
130	#[derive(Debug, Clone, PartialEq, Eq)]
131	pub struct Policy {
132	    /// `scaling_driver`, e.g. `amd-pstate-epp`.
133	    pub driver: Option<PolicyField>,
134	    /// `scaling_governor`, e.g. `powersave`.
135	    pub governor: Option<PolicyField>,
136	    /// `energy_performance_preference`, absent outside EPP-capable drivers.
137	    pub epp: Option<PolicyField>,
138	    /// `boost` as its raw `1` / `0` token.
139	    pub boost: Option<PolicyField>,
140	    /// `scaling_min_freq` (kHz) as its raw token: the governor's lower clamp. With the upper
141	    /// clamp and boost it is what makes a pinned run verifiable from its record: a pin sets
142	    /// min = max, and a record carrying the clamp shows it.
143	    pub scaling_min_freq: Option<PolicyField>,
144	    /// `scaling_max_freq` (kHz) as its raw token: the governor's upper clamp.
145	    pub scaling_max_freq: Option<PolicyField>,
146	}
147	
148	/// Read the box's cpufreq policy; each field independently `None` when its file is absent.
149	pub fn policy() -> Policy {
150	    let cpus = cpus();
151	    Policy {
152	        driver: read_field(&cpus, "scaling_driver"),
153	        governor: read_field(&cpus, "scaling_governor"),
154	        epp: read_field(&cpus, "energy_performance_preference"),
155	        boost: read_boost(&cpus),
156	        scaling_min_freq: read_field(&cpus, "scaling_min_freq"),
157	        scaling_max_freq: read_field(&cpus, "scaling_max_freq"),
158	    }
159	}
160	
161	/// Logical CPUs sysfs knows about, ascending; empty when the directory is unreadable.
162	fn cpus() -> Vec<usize> {
163	    let Ok(dir) = std::fs::read_dir("/sys/devices/system/cpu") else {
164	        return Vec::new();
165	    };
166	    let mut cpus: Vec<usize> = dir
167	        .flatten()
168	        .filter_map(|e| {
169	            let name = e.file_name();
170	            let name = name.to_str()?;
171	            name.strip_prefix("cpu")?.parse().ok()
172	        })
173	        .collect();
174	    cpus.sort_unstable();
175	    cpus
176	}
177	
178	/// One policy field across every CPU: the first reading plus whether the rest agree.
179	fn read_field(cpus: &[usize], name: &str) -> Option<PolicyField> {
180	    let mut values = cpus.iter().filter_map(|&cpu| read_token(cpu, name));
181	    let value = values.next()?;
182	    let uniform = values.all(|v| v == value);
183	    Some(PolicyField { value, uniform })
184	}
185	
186	/// `boost` per CPU, falling back to the single global knob (uniform by construction).
187	fn read_boost(cpus: &[usize]) -> Option<PolicyField> {
188	    if let Some(field) = read_field(cpus, "boost") {
189	        return Some(field);
190	    }
191	    let raw = std::fs::read_to_string("/sys/devices/system/cpu/cpufreq/boost").ok()?;
192	    Some(PolicyField {
193	        value: raw.trim().to_string(),
194	        uniform: true,
195	    })
196	}
197	
198	/// One cpufreq sysfs value for `cpu` as a trimmed token, `None` when the file is absent.
199	fn read_token(cpu: usize, name: &str) -> Option<String> {
200	    let path = format!("/sys/devices/system/cpu/cpu{cpu}/cpufreq/{name}");
201	    Some(std::fs::read_to_string(path).ok()?.trim().to_string())
202	}
203	
204	#[cfg(test)]
205	mod tests {
206	    use super::*;
207	
208	    #[test]
209	    fn current_cpu_resolves() {
210	        assert!(current_cpu().is_some());
211	    }
212	
213	    #[test]
214	    fn absent_file_reads_none() {
215	        assert_eq!(read_khz(usize::MAX, "cpuinfo_avg_freq"), None);
216	    }
217	}
