436	/// When the warmup stretch settled, and at what clock: seconds from warmup start to the start
437	/// of the earliest suffix of the stretch that grades A on timing *and* held its delivered
438	/// clock still, plus that suffix's median frequency when readable. `None` when there is
439	/// nothing to measure (an empty stretch or a `tail_len` the stretch cannot hold).
440	///
441	/// - **Why report it at all.** Once warmup deliberately spans the ramp, the grade stops seeing
442	///   the ramp, which is warmup working, and would otherwise leave the report saying nothing
443	///   about a box that took a second to come up to speed. The letter answers "was it settled
444	///   when measurement started"; this answers "how long did that take", and at what state.
445	/// - **Settled means "graded A from here on, at one clock"**: the timing test is the letter's
446	///   own computation, and the clock gate is [`crate::freq::clock_stable`], the warm exit's
447	///   second gate, shared so the cell cannot claim settled where the exit would not. Timing
448	///   alone was the whole cell until 0.26.0-1, and a box parked flat on its un-boosted base
449	///   clock graded A immediately, so the 3900X under `powersave` read `0.01s` and then
450	///   transitioned mid-bench to an F (2026-08-15).
451	/// - **The named state is the point.** A settle time alone cannot distinguish "settled at the
452	///   top" from "parked at base clock", and the parked case is the one that scatters later, so
453	///   the cell carries the settled suffix's median GHz whenever the driver exposed one.
454	/// - `clock` is the delivered-frequency series sampled beside `warm`, index-parallel
455	///   ([`crate::freq::FreqSample`] per probe); a shorter series is aligned at the end, and
456	///   missing samples fall back to timing-only inside the gate.
457	/// - `tail_len` is the exit window's probe count ([`ProbeSummary`] count, the caller's
458	///   `RunOutput::warm_tail`): the shortest suffix the exit condition certified. The scan never
459	///   considers a shorter one, so a settle time is always backed by at least the window the
460	///   letter was scored over, and a settled exit always finds one ([`Settle::Never`] can only
461	///   reach the report on a cap exit, both gates having passed on the exit window itself).
462	pub fn settle(
463	    warm: &[ProbeSummary],
464	    clock: &[Option<crate::freq::FreqSample>],
465	    tail_len: usize,
466	) -> Option<Settle> {
467	    if warm.is_empty() || tail_len == 0 || tail_len > warm.len() {
468	        return None;
469	    }
470	    let offset = clock.len().saturating_sub(warm.len());
471	    for start in 0..=(warm.len() - tail_len) {
472	        let clock_suffix = &clock[(offset + start).min(clock.len())..];
473	        if EnvGrade::from_probes(&warm[start..]).is_some_and(|g| g.letter == 'A')
474	            && crate::freq::clock_stable(clock_suffix)
475	        {
476	            return Some(Settle::At {
477	                t_s: warm[start].t_start_s,
478	                ghz: median_ghz(clock_suffix),
479	            });
480	        }
481	    }
482	    Some(Settle::Never)
483	}
484	
485	/// Median delivered frequency (GHz) of a clock-sample window, `None` when no sample in it was
486	/// readable. The median rather than an endpoint, so one odd read cannot name the state.
487	fn median_ghz(clock: &[Option<crate::freq::FreqSample>]) -> Option<f64> {
488	    let mut khz: Vec<u64> = clock.iter().flatten().map(|f| f.khz).collect();
489	    if khz.is_empty() {
490	        return None;
491	    }
492	    khz.sort_unstable();
493	    Some(khz[khz.len() / 2] as f64 / 1_000_000.0)
